          .replaceAll('"', "&quot;")
          .replaceAll("<", "&lt;")
          .replaceAll(">", "&gt;");
      }

      function FieldComponent(field) {
        const errorId = `${field.id}-error`;
        const helperId = field.helperText ? `${field.id}-helper` : "";
        const describedBy = [helperId, errorId].filter(Boolean).join(" ");

        return `
          <div class="form-field">
            <label for="${field.id}">
              ${field.label}${field.required ? ' <span class="required-note">(required)</span>' : ""}
            </label>
            <input
              id="${field.id}"
              name="${field.id}"
              type="${field.type}"
              placeholder="${field.placeholder}"
              autocomplete="${field.autocomplete}"
              ${field.required ? "required" : ""}
              aria-required="${field.required ? "true" : "false"}"
              aria-invalid="${state.errors[field.id] ? "true" : "false"}"
              aria-describedby="${describedBy}"
              value="${escapeAttribute(state.values[field.id])}"
            >
            ${field.helperText ? `<p class="helper-text" id="${helperId}">${field.helperText}</p>` : ""}
            <p class="error-message" id="${errorId}" aria-live="polite">${state.errors[field.id]}</p>
          </div>
        `;
      }

      function SupportForm() {
        return `
          <section class="support-card" aria-labelledby="support-title">
            <p class="eyebrow">Support</p>
            <h1 id="support-title">How can we help?</h1>
            <p class="intro">
              Send our support team your contact details and we will get back to you with the next best step.
            </p>
