              ${fields.map(FieldComponent).join("")}
              <button type="submit">Submit request</button>
              <p class="success-message" id="form-status" aria-live="polite">
                ${state.submitted ? "Thanks. Your support request is ready to send." : ""}
              </p>
            </form>
          </section>
        `;
      }

      function render() {
        document.getElementById("app").innerHTML = SupportForm();
        bindEvents();
      }

      function bindEvents() {
        const form = document.getElementById("support-form");

        fields.forEach((field) => {
          const input = document.getElementById(field.id);

          input.addEventListener("input", (event) => {
            state.values[field.id] = event.target.value;
            state.errors[field.id] = validateField(field, event.target.value);
            state.submitted = false;
            render();
            document.getElementById(field.id).focus();
          });

          input.addEventListener("blur", (event) => {
            state.values[field.id] = event.target.value;
            state.errors[field.id] = validateField(field, event.target.value);
            render();
          });
        });

        form.addEventListener("submit", (event) => {
          event.preventDefault();

          fields.forEach((field) => {
            state.values[field.id] = document.getElementById(field.id).value;
            state.errors[field.id] = validateField(field, state.values[field.id]);
          });

          const firstInvalidField = fields.find((field) => state.errors[field.id]);
          state.submitted = !firstInvalidField;
          render();

          if (firstInvalidField) {
            document.getElementById(firstInvalidField.id).focus();
          }
        });
      }

      render();
    </script>
  </body>
