        transition:
          background 160ms ease,
          box-shadow 160ms ease,
          transform 160ms ease;
      }

      button:hover {
        background: linear-gradient(135deg, var(--primary-dark), #4338ca);
        box-shadow: 0 1.2rem 2.3rem rgba(37, 99, 235, 0.34);
        transform: translateY(-1px);
      }

      button:focus {
        box-shadow: 0 0 0 0.25rem var(--focus), 0 1rem 2rem rgba(37, 99, 235, 0.28);
        outline: none;
      }

      .success-message {
        border-radius: 0.9rem;
        color: #067647;
        font-weight: 700;
        margin: 0;
        min-height: 1.5rem;
      }

      @media (max-width: 36rem) {
        body {
          place-items: start center;
        }

        .support-card {
          border-radius: 1.1rem;
        }
      }
    </style>
  </head>
  <body>
    <main id="app"></main>

    <script>
      const fields = [
        {
          id: "fullName",
          label: "Full name",
          type: "text",
          placeholder: "Alex Morgan",
          autocomplete: "name",
          required: true,
          requiredMessage: "Enter your full name."
        },
        {
          id: "email",
          label: "Email address",
          type: "email",
          placeholder: "alex@example.com",
          autocomplete: "email",
          required: true,
          requiredMessage: "Enter your email address.",
          patternMessage: "Enter a valid email address, such as alex@example.com.",
          pattern: /^[^\s@]+@[^\s@]+\.[^\s@]+$/
        },
        {
          id: "phone",
          label: "Phone number",
          type: "tel",
          placeholder: "(555) 123-4567",
          autocomplete: "tel",
          required: false,
          helperText: "Expected format: 10 digits, such as (555) 123-4567.",
          patternMessage: "Enter a 10-digit phone number, such as (555) 123-4567.",
          pattern: /^(?:\+?1[\s.-]?)?(?:\([2-9]\d{2}\)|[2-9]\d{2})[\s.-]?[2-9]\d{2}[\s.-]?\d{4}$/
        }
      ];

      const state = {
        values: Object.fromEntries(fields.map((field) => [field.id, ""])),
        errors: Object.fromEntries(fields.map((field) => [field.id, ""])),
        submitted: false
      };

      function validateField(field, value) {
        const trimmedValue = value.trim();

        if (field.required && !trimmedValue) {
          return field.requiredMessage;
        }

        if (trimmedValue && field.pattern && !field.pattern.test(trimmedValue)) {
          return field.patternMessage;
        }

        return "";
      }

      function escapeAttribute(value) {
        return value
          .replaceAll("&", "&amp;")
          .replaceAll('"', "&quot;")
          .replaceAll("<", "&lt;")
          .replaceAll(">", "&gt;");
      }

      function FieldComponent(field) {
        const errorId = `${field.id}-error`;
        const helperId = field.helperText ? `${field.id}-helper` : "";
        const describedBy = [helperId, errorId].filter(Boolean).join(" ");

        return `
          <div class="form-field">
            <label for="${field.id}">
              ${field.label}${field.required ? ' <span class="required-note">(required)</span>' : ""}
            </label>
            <input
              id="${field.id}"
              name="${field.id}"
              type="${field.type}"
              placeholder="${field.placeholder}"
              autocomplete="${field.autocomplete}"
              ${field.required ? "required" : ""}
              aria-required="${field.required ? "true" : "false"}"
              aria-invalid="${state.errors[field.id] ? "true" : "false"}"
              aria-describedby="${describedBy}"
              value="${escapeAttribute(state.values[field.id])}"
            >
            ${field.helperText ? `<p class="helper-text" id="${helperId}">${field.helperText}</p>` : ""}
            <p class="error-message" id="${errorId}" aria-live="polite">${state.errors[field.id]}</p>
          </div>
        `;
      }

      function SupportForm() {
        return `
          <section class="support-card" aria-labelledby="support-title">
            <p class="eyebrow">Support</p>
            <h1 id="support-title">How can we help?</h1>
            <p class="intro">
              Send our support team your contact details and we will get back to you with the next best step.
            </p>
            <form id="support-form" novalidate>
              ${fields.map(FieldComponent).join("")}
              <button type="submit">Submit request</button>
              <p class="success-message" id="form-status" aria-live="polite">
                ${state.submitted ? "Thanks. Your support request is ready to send." : ""}
              </p>
            </form>
          </section>
        `;
      }

      function render() {
        document.getElementById("app").innerHTML = SupportForm();
        bindEvents();
      }

      function bindEvents() {
        const form = document.getElementById("support-form");

        fields.forEach((field) => {
          const input = document.getElementById(field.id);

          input.addEventListener("input", (event) => {
            state.values[field.id] = event.target.value;
            state.errors[field.id] = validateField(field, event.target.value);
            state.submitted = false;
            render();
            document.getElementById(field.id).focus();
          });

          input.addEventListener("blur", (event) => {
            state.values[field.id] = event.target.value;
            state.errors[field.id] = validateField(field, event.target.value);
            render();
          });
        });

        form.addEventListener("submit", (event) => {
          event.preventDefault();

          fields.forEach((field) => {
            state.values[field.id] = document.getElementById(field.id).value;
            state.errors[field.id] = validateField(field, state.values[field.id]);
          });

          const firstInvalidField = fields.find((field) => state.errors[field.id]);
          state.submitted = !firstInvalidField;
          render();

          if (firstInvalidField) {
            document.getElementById(firstInvalidField.id).focus();
          }
        });
      }

      render();
    </script>
  </body>
</html>
